begin;create extension if not exists pgtap with schema extensions;select plan(8);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)values('dd000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ops-admin@test.invalid','',now(),now(),now(),'{}','{"name":"Ops Admin"}'),('dd000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','ops-student@test.invalid','',now(),now(),now(),'{}','{"name":"Ops Student"}');update public.profiles set account_status='active'where id::text like'dd000000-%';insert into public.administrators(user_id,status)values('dd000000-0000-4000-8000-000000000001','active');
set local role anon;select set_config('request.jwt.claims','{"role":"anon"}',true);select is((select count(*)from public.get_public_feature_flags()),3::bigint,'public flags expose only controlled keys');select throws_ok($$select * from public.feature_flags$$,'42501','permission denied for table feature_flags','raw flag table is private');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"dd000000-0000-4000-8000-000000000002","role":"authenticated"}',true);select throws_ok($$select * from public.get_admin_system_health()$$,'42501','ADMIN_ACCESS_REQUIRED','student cannot inspect system health');select throws_ok($$select * from public.operation_rate_limits$$,'42501','permission denied for table operation_rate_limits','rate-limit ledger is private');
select set_config('request.jwt.claims','{"sub":"dd000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select is((select count(*)from public.get_admin_system_health()),4::bigint,'admin health checks core components');select ok(public.update_feature_flag('ai_missions',true),'admin updates a remote flag');select ok((select enabled from public.get_public_feature_flags()where flag_key='ai_missions'),'updated flag is published');select throws_ok($$select * from public.get_admin_certificates_page(null,'all',100,0)$$,'22023','INVALID_PAGE','pagination has a safe maximum');select*from finish();rollback;
